package com.nodecockpit.customization;
import org.junit.Test;import static org.junit.Assert.*;
public class EdgeOverlayPolicyTest {
 @Test public void unknownNeverAuthorizesAnOverlay(){EdgeOverlayPolicy p=new EdgeOverlayPolicy();assertTrue(p.blocked());p.bar("");p.task(null,null);assertTrue(p.blocked());p.task("com.example.app","ChatActivity");assertFalse(p.blocked());p.reset();assertTrue(p.blocked());}
 @Test public void eitherPermissionEvidenceKeepsWindowsSuppressed(){EdgeOverlayPolicy p=new EdgeOverlayPolicy();p.task("com.example.app","ChatActivity");p.bar("com.google.android.permissioncontroller");assertTrue(p.blocked());p.task("com.example.app","ChatActivity");assertTrue(p.blocked());p.bar("com.example.app");assertFalse(p.blocked());p.task("com.google.android.permissioncontroller","GrantPermissionsActivity");p.bar("com.example.app");assertTrue(p.blocked());p.task("com.example.app","ChatActivity");assertFalse(p.blocked());}
 @Test public void sensitiveTaskLeavingCanClearStaleBarEvidence(){EdgeOverlayPolicy p=new EdgeOverlayPolicy();p.bar("com.android.permissioncontroller");p.task("com.android.permissioncontroller","GrantPermissionsActivity");assertTrue(p.blocked());p.task("com.example.app","MainActivity");assertFalse(p.blocked());}
 @Test public void installerCredentialsAndResolvedVendorPermissionsAreCovered(){EdgeOverlayPolicy p=new EdgeOverlayPolicy();p.permissionPackage("vendor.permissions");for(String pkg:new String[]{"com.android.settings","com.android.packageinstaller","com.google.android.packageinstaller","vendor.permissions"})assertTrue(p.sensitive(pkg,"Main"));assertTrue(p.sensitive("vendor.app","GrantPermissionsActivity"));assertTrue(p.sensitive("vendor.app","ConfirmDeviceCredentialActivity"));assertTrue(p.sensitive("com.android.systemui","BiometricPromptActivity"));assertFalse(p.sensitive("com.openai.chatgpt","ChatActivity"));}
 @Test public void cancellingAClosedHandleCannotCreateAFullscreenWindow(){assertFalse(EdgeOverlayPolicy.needsModal(false,0));assertFalse(EdgeOverlayPolicy.needsModal(false,-1));assertTrue(EdgeOverlayPolicy.needsModal(false,.01f));assertTrue(EdgeOverlayPolicy.needsModal(true,0));}
}
